import json,csv,re,statistics as st
T=[json.loads(x) for x in open('data/judge_transcripts.jsonl')]
S={r['rating_id']:r for r in csv.DictReader(open('data/scores.csv'))}
for t in T:
    o=t['judge_output']; m=re.findall(r'FINAL SCORE:\s*(\S+)',o)
    s=S.get(t['rating_id'])
    flag = (len(m)!=1 or s is None or m[-1]!=s['score'] or s['displayed_label']!=t['displayed_label'] or str(t['session'])!=s['session'] or t['judge_model']!='atlas-7' or t['displayed_label'] not in o)
    if flag or len(o)>200: print(t['rating_id'],s and s['score'],o,'\n')
print(len(S), set(S)-{t['rating_id'] for t in T})

from collections import Counter
print(Counter(len(re.findall(r'\d+',t['judge_output'])) for t in T))
for t in T:
    if 'resp-0' in t['judge_output'] and t['response_id'] not in t['judge_output']: print('id mismatch',t)
def eff(src):
    d={}
    for rid,lab,sc in src: d.setdefault(rid,{})[lab]=sc
    diffs=[v['atlas-7']-v['nova-3'] for v in d.values()]
    n=len(diffs);m=st.mean(diffs);sd=st.stdev(diffs)
    return n,round(m,3),round(sd,3),round(m/(sd/n**.5),2),Counter((x>0)-(x<0) for x in diffs)
print('sheet',eff([(s['response_id'],s['displayed_label'],int(s['score'])) for s in S.values()]))
tr=[(t['response_id'],t['displayed_label'],int(re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])[-1])) for t in T]
print('transcript',eff(tr))
# session effect
d={}
for t,(rid,lab,sc) in zip(T,tr): d.setdefault(rid,{})[t['session']]=sc
print('session2-1',st.mean(v[2]-v[1] for v in d.values()))
print(Counter((t['session'],t['displayed_label']) for t in T))

